encoder.code:
volatile long count = 0;
const int PPR = 600; // pulses per rotation
void setup() {
 pinMode(2, INPUT_PULLUP);
 pinMode(3, INPUT_PULLUP);
 attachInterrupt(digitalPinToInterrupt(2), encoderISR, RISING);
 Serial.begin(9600);
}
void loop() {
 float rotations;
 noInterrupts();
 rotations = (float)count / PPR;
 interrupts();
 Serial.print("Rotations: ");
 Serial.println((int)rotations);
 delay(50);
}
void encoderISR() {
 if (digitalRead(3) == HIGH) count++;
 else count--;
}

