#include <Wire.h>
#include "Adafruit_VL53L0X.h"
Adafruit_VL53L0X lox = Adafruit_VL53L0X();
void setup() {
 Serial.begin(9600);
 Wire.begin(); // Uses Mega I2C pins 20 & 21 automatically
 if (!lox.begin()) { Serial.println("VL53L0X not detected"); while (1); }
 Serial.println("VL53L0X Ready");
}
void loop() {
 VL53L0X_RangingMeasurementData_t measure;
 lox.rangingTest(&measure, false);
 if (measure.RangeStatus != 4) {
  Serial.print("Distance: "); Serial.print(measure.RangeMilliMeter / 10.0);
  Serial.println(" cm");
 } else { Serial.println("Out of range"); }
 delay(300);
}
